// Допоміжні функції для роботи з DOM, повідомленнями та іншими утилітами
// Експортуємо функцію для показу HTML елемента на сторінці
// Функція приймає параметр element типу HTMLElement і не повертає значення (void)
export function showElement(element) {
    // Видаляє CSS клас 'hidden' з елемента, роблячи його видимим на сторінці
    // Це працює за умови, що в CSS є стиль для класу .hidden { display: none; }
    element.classList.remove('hidden');
}
// Експортуємо функцію для приховування HTML елемента зі сторінки
// Функція приймає параметр element типу HTMLElement і не повертає значення (void)
export function hideElement(element) {
    // Додає CSS клас 'hidden' до елемента, що робить його невидимим на сторінці
    // Елемент залишається в DOM, але не відображається користувачеві
    element.classList.add('hidden');
}
// Експортуємо функцію для відображення повідомлень про помилки
// Функція приймає параметр message типу string і не повертає значення (void)
export function showError(message) {
    // Виводить повідомлення про помилку в консоль розробника браузера
    // Це допомагає при налагодженні та відловлюванні помилок
    console.error(message);
    // Показує повідомлення у вигляді спливаючого вікна alert
    // Це інформує користувача про помилку у зрозумілій формі
    alert(message);
}
// Експортуємо функцію для відображення спливаючих повідомлень (тостів)
// Функція приймає обов'язковий параметр message і опціональний параметр type з значенням за замовчуванням 'success'
// Тип type може бути тільки 'success', 'error' або 'warning'
export function showToast(message, type = 'success') {
    // Виводить повідомлення в консоль з відповідним типом (великими літерами)
    // Наприклад: "[SUCCESS] Товар успішно додано до кошика"
    console.log(`[${type.toUpperCase()}] ${message}`);
    // У реальному додатку тут була б реалізація красивих спливаючих повідомлень (toast)
    // Але поки що використовуємо alert для демонстрації функціоналу
    // В майбутньому тут можна додати створення HTML елемента тоста з анімацією
    alert(message);
}
// Експортуємо функцію для генерації HTML представлення зірочкового рейтингу
// Функція приймає числовий параметр rating (рейтинг від 0 до 5) і повертає рядок
export function generateStarRating(rating) {
    // Обчислюємо кількість повних зірочок (ціла частина рейтингу)
    // Наприклад, для рейтингу 4.3 fullStars буде 4
    const fullStars = Math.floor(rating);
    // Визначаємо, чи потрібна половина зірочки (якщо дробова частина >= 0.5)
    // Наприклад, для рейтингу 4.3 halfStar буде false, для 4.7 - true
    const halfStar = rating % 1 >= 0.5;
    // Обчислюємо кількість порожніх зірочок
    // Від загальної кількості зірочок (5) віднімаємо повні зірочки та половину (якщо є)
    const emptyStars = 5 - fullStars - (halfStar ? 1 : 0);
    // Повертаємо рядок, який складається з:
    // - повних зірочок (символ '★'), повторені fullStars разів
    // - половини зірочки (символ '½'), якщо halfStar дорівнює true
    // - порожніх зірочок (символ '☆'), повторені emptyStars разів
    // Наприклад, для рейтингу 4.5: "★★★★½"
    return '★'.repeat(fullStars) + (halfStar ? '½' : '') + '☆'.repeat(emptyStars);
}
